    videos = [item for item in videos if isinstance(item, dict) and re.fullmatch(r"[A-Za-z0-9_-]{11}", str(item.get("videoId") or ""))]
    if not videos:
        videos = VIDEO_SEED
    cards = ''.join(video_card(item, locale) for item in videos)
    empty = "No videos found yet." if locale == "en" else "TodavÃ­a no hay vÃ­deos."
    labels = {"close": "Close video" if locale == "en" else "Cerrar vÃ­deo", "play": "Play video" if locale == "en" else "Reproducir vÃ­deo"}
