        video_description = "Watch our latest mould demonstrations, factory tours, and technical insights." if code == "en" else "Vea nuestras demostraciones de moldes y conocimientos tÃ©cnicos."
        video_body = video_page(code)
        add(code, "/video/", video_title, video_description, video_body)
